const safeURL=value=>{try{const u=new URL(value);return ['https:','http:'].includes(u.protocol)?u.href:'#'}catch{return '#'}};
const billions=(value,unit=obs(state.code)?.fundamentals?.currency||byCode(state.code)?.currency||'CNY')=>E.valid(value)?num(value/1e8,2)+'亿'+({CNY:'元',CNH:'离岸人民币',HKD:'港元',USD:'美元'}[unit]||unit):'—';
function ctx(code=state.code){const a=byCode(code),r=obs(code)||{},bars=series(code),m=E.metrics(bars),closed=E.metrics(series(code,{includeLive:false})),f=r.fundamentals||{},benchmark=(a.market==='US'?'QQQ':a.market==='HK'?'恒生科技':'沪深300'),bm=E.metrics(a.market&&a.market!=='CN'?(data().external||[]).find(x=>x.symbol===(a.market==='US'?'usQQQ':'hkHSTECH'))?.history||[]:series('510300')),flows=(r.flows||[]).filter(x=>E.valid(x.netFlow)).slice().sort((a,b)=>a.date.localeCompare(b.date)),sum=n=>flows.length>=n?flows.slice(-n).reduce((v,x)=>v+x.netFlow,0):null;return {a,r,bars,m,closed,f,benchmark,flows,flow5:sum(5),flow20:sum(20),rel20:E.valid(m?.ret20)&&E.valid(bm?.ret20)?m.ret20-bm.ret20:null,events:r.announcements||[],live:bars.at(-1)?.completed===false,etf:r.etf||{},nav:r.nav||null}}
function provenance(c){const f=c.f,r=c.r;return `<div class="provenance">行情 ${esc(r.latest_quote?.timestamp?.replace('T',' ')||r.as_of||'未载入')} · ${esc(r.source||'来源待接入')}${f.period?`<br>财务报告期 ${esc(f.period)} · 披露 ${esc(f.notice_date||'—')} · ${esc(f.source||'')}${f.period_basis?' · '+esc(f.period_basis):''}`:''}${c.flows.length?`<br>资金流截至 ${c.flows.at(-1).date} · 新浪超大单+大单净额；不等于机构身份`:''}</div>`}
function sourceLink(url,label){return `<a href="${esc(safeURL(url))}" target="_blank" rel="noopener">${esc(label)} ↗</a>`}
function finding(title,text,condition,tone='neutral'){return `<div class="finding ${tone}"><h3>${title}</h3><p>${text}</p><small><strong>后续验证：</strong>${condition}</small></div>`}
function financialRead(c){const f=c.f;if(!E.valid(f.revenueGrowth))return finding('财务数据不可用','本次来源未提供可验证的财务报告，不能据此推导经营改善。','查看连接详情中的具体失败原因，或导入带报告期与来源的数据。','warn');const cash=E.valid(f.operatingCash)?`经营现金净额${billions(f.operatingCash)}，现金/净利润${num(f.cashRatio)}倍。`:'经营现金流尚未获取。';const view=f.operatingCash<0?'利润增长尚未得到正向经营现金流支持，需要检查库存、应收及预付款的资金占用。':E.valid(f.cashRatio)&&f.cashRatio<1?'经营现金流为正但弱于净利润，仍需检查利润兑现速度。':'经营现金流对利润形成一定支持，仍需核对资本开支及持续性。';return finding('增长与现金兑现',`截至${f.period}的累计营收同比${change(f.revenueGrowth)}，归母净利同比${change(f.profitGrowth)}。${cash}${view}`,`下一报告期重点核对收入/利润、存货周转${num(f.inventoryDays,0)}天与应收周转${num(f.receivableDays,0)}天能否同步改善。`,f.operatingCash<0?'warn':'good')}
function sentimentRead(c){const f=c.f,pressure=(E.valid(c.m?.ret120)&&c.m.ret120<=-20)||(E.valid(c.rel20)&&c.rel20<=-20),health=f.profit>0&&f.deductProfit>0&&f.operatingCash>0&&f.revenueGrowth>0;let label,text;if(!c.m){label='价格证据不足';text='缺少价格序列，不能识别情绪压力。'}else if(pressure&&health){label='价格与经营出现分化';text=`价格压力与正利润、正经营现金流同时存在，可继续验证情绪偏离；尚不足以直接认定“错杀”。`}else if(pressure&&E.valid(f.operatingCash)&&f.operatingCash<0){label='价格与现金流同步承压';text='财务侧也出现压力，不能把下跌全部解释为市场情绪。'}else if(pressure){label='价格承压，经营证据尚不完整';text='需要进一步排除经营、治理或周期的结构性变化。'}else{label='当前未触发强价格背离筛选';text=`未满足近120观察日跌幅≥20%或20日相对${c.benchmark}落后≥20个百分点的研究阈值。`}return {label,pressure,health,text}}
function valuationRead(c){const f=c.f;if(!E.valid(f.pe)&&!E.valid(f.ps))return finding('估值口径尚不完整','没有可靠TTM盈利或收入时，不给出固定“合理倍数”结论。','先核对报告期、币种、总股本与亏损处理。','warn');return finding('估值隐含的兑现要求',`按${esc(f.valuation_date||'当前快照')}价格与最近披露总股本重建，PE（TTM）${num(f.pe,1)}倍、PB ${num(f.pb,1)}倍、PS（TTM）${num(f.ps,1)}倍。${E.valid(f.pe)?'对应历史盈利收益率约'+num(100/f.pe)+'%。':''}${E.valid(f.revenueGrowth)?'累计收入增长'+change(f.revenueGrowth)+'，并不等同未来增长。':''}`,c.a.questions?.[2]||'用后续实际盈利、现金流及业务可比公司验证，不能机械套固定PE。')}
function trendRead(c){if(!c.m?.ma60)return finding('趋势预热不足','不足60条有效日线时，长期趋势判断保持空缺。','样本积累后再观察均线及信号。','warn');const m=c.m,below=m.price<m.ma60;return finding('趋势与量价',`最新价${num(m.price,3)}，${below?'低于':'高于'}MA60 ${num(m.ma60,3)}；20日涨跌${change(m.ret20)}，距近60日最高收盘${change(m.drawdown)}。${c.live?'当前K线尚未收盘；当日量比未按盘中时段校准。':''}`,below?'观察能否收复MA20/MA60并持续，而不是仅凭一次金叉认定反转。':'观察是否守住MA20/MA60，以及价格上涨是否得到成交与资金统计支持。',below?'warn':'good')}
function flowRead(c){if(c.a.type==='etf')return finding('成交活跃度不等于净申购',`当前累计成交量${num(c.bars.at(-1)?.vol,0)}份，量比${num(c.m?.vr)}。交易成交量可以观测，但不等于ETF份额新增。`,'后续需用基金份额变化与净值估算申赎，不能用股票大单口径替代。');if(!c.flows.length)return finding('资金统计未返回','行情商未提供有效历史资金流，本页不将缺失补为0。','查看本次取数错误及日期；必要时更换有授权的数据源。','warn');return finding('价格与分类资金交叉验证',`资金统计截至${c.flows.at(-1).date}：近5条观察合计${billions(c.flow5)}，近20条观察合计${billions(c.flow20)}。${c.flow5<0?'近期大单分类净额偏流出，需观察价格弱势是否持续。':'近期大单分类净额偏流入，仍需价格和现金经营证据确认。'}`,'这是供应商交易分类统计，不代表已识别机构真实买卖。最新交易日若缺数据，不推算当日净额。',c.flow5<0?'warn':'good')}
function etfRead(c){const h=c.etf.holdings||[];return finding('ETF的风险来自成分暴露',h.length?`${c.etf.period}披露${h.length}只持股，前十占净值${num(c.etf.top10_weight)}%。前列为${h.slice(0,3).map(x=>x.name+' '+num(x.weight)+'%').join('、')}。${c.etf.top10_weight>=50?'头部权重较集中，指数内分散不等于产业风险分散。':'仍需穿透行业与共同风险因子。'}`:'持仓来源尚未返回；不能套用经营公司的营收与ROE指标。','季报持仓存在披露滞后，不能当作今日实时持仓。',h.length?'good':'warn')}
function holdingsTable(c){const h=c.etf.holdings||[];return h.length?`<div class="table-wrap"><table><thead><tr><th>披露持股</th><th>代码</th><th>占净值</th></tr></thead><tbody>${h.slice(0,12).map(x=>`<tr><td>${esc(x.name)}</td><td>${x.code}</td><td class="num">${num(x.weight)}%</td></tr>`).join('')}</tbody></table></div><div class="panel-note">${c.etf.period} · ${sourceLink(c.etf.url,c.etf.source)}</div>`:'<div class="empty">本次ETF持仓接口未返回；错误和来源保留在数据页。</div>'}
function eventList(c){return c.events.length?`<div class="panel-body event-list">${c.events.map(e=>`<article><small>${esc(e.date)} · ${esc((e.categories||[]).join(' / '))}</small><p>${sourceLink(e.url,e.title)}</p></article>`).join('')}</div>`:`<div class="panel-body">${finding('公告来源尚未返回','没有返回公告记录不代表“没有公告”或“没有风险”。','请以数据页错误与上市公司原文披露为准。','warn')}</div>`}
function dimData(c,i){const f=c.f,m=c.m,etf=c.a.type==='etf',s=latestSignal(c.a.code),gap=sentimentRead(c),stock=[
 {rows:[['20日涨跌',change(m?.ret20)],['相对'+c.benchmark+'（各自20日）',E.valid(c.rel20)?num(c.rel20)+'个百分点':'—'],['行业标签',c.a.industry]],read:trendRead(c),extra:panel('产业验证问题',`<div class="panel-body"><ul class="research-questions">${c.a.questions.map(q=>`<li>${q}</li>`).join('')}</ul><p class="small muted">价格相对宽基不等于相对同业；订单、客户及产品证据需与公告/财报核对。</p></div>`)},
 {rows:[['营收 / 归母净利',billions(f.revenue)+' / '+billions(f.profit)],['收入 / 净利累计同比',change(f.revenueGrowth)+' / '+change(f.profitGrowth)],['经营现金 / 自由现金',billions(f.operatingCash)+' / '+billions(f.freeCashFlow)],['ROE / 毛利率',change(f.roe)+' / '+change(f.grossMargin)]],read:etf?etfRead(c):financialRead(c),extra:etf?holdingsTable(c):financialHistory(c)},
 {rows:etf?[['单位净值',c.nav?num(c.nav.value,4):'—'],['净值日期',c.nav?.date||'—'],['相对该净值变化',c.nav?change((m?.price/c.nav.value-1)*100):'—']]:[['PE / PB',num(f.pe,1)+' / '+num(f.pb,1)],['PS（TTM）',num(f.ps,1)],['估值基准',f.valuation_date||'—']],read:etf?finding('净值与交易价格',c.nav?`单位净值${num(c.nav.value,4)}截至${c.nav.date}，当前价格${num(m?.price,3)}。${c.nav.date===c.r.as_of?'可比较同日收盘折溢价。':'两者日期不同，差值包含期间市场涨跌，不能称实时折溢价。'}`:'净值尚未返回，不能计算折溢价。','同日净值或实时IOPV可用后再核实。'):valuationRead(c)},
 {rows:[['近5条大单净额',billions(c.flow5)],['近20条大单净额',billions(c.flow20)],['最新资金日期',c.flows.at(-1)?.date||'不适用 / 未返回'],['报价换手率',change(c.r.latest_quote?.turnover)]],read:flowRead(c),extra:flowTable(c)},
 {rows:[['MA10 / MA20 / MA60',num(m?.ma10,3)+' / '+num(m?.ma20,3)+' / '+num(m?.ma60,3)],['20日年化波动',change(m?.vol20)],['量比（未按时段调整）',num(m?.vr)],['最近信号',s?(s.provisional?'盘中暂定 ':'收盘确认 ')+(s.type==='buy'?s.grade+'级笑脸':'哭脸')+' · '+s.date:'预热不足或无信号']],read:trendRead(c),extra:`<div class="panel-body">${button('查看交互K线与回测',"go('backtest')",true,'chart')}</div>`},
 {rows:[['近120观察日',change(m?.ret120)],['60日高点回撤',change(m?.drawdown)],['经营证据',etf?'穿透成分验证':f.operatingCash>0?'经营现金为正':E.valid(f.operatingCash)?'经营现金为负':'财务未返回']],read:finding(gap.label,gap.text,'情绪偏离模型不把价格下跌等同错杀；一致预期与独立舆情未接入时，不输出概率或偏差总分。',gap.pressure?'warn':'neutral')},
 {rows:[['已载入公告',c.events.length+'条'],['最近披露',c.events[0]?.date||'—'],['财报披露',f.notice_date||c.etf.period||'—']],read:finding('治理与事件需要读原文',c.events.length?`本次保留${c.events.length}条公告及分类、日期和原文链接。${c.events.some(e=>/关联交易|控股股东|减持|质押|诉讼|问询/.test(e.title))?'存在需关注的治理类标题，标题匹配仅用于定位原文，不代表已证实负面事件。':'公告标题不等于事件影响结论。'}`:'缺少原文索引，不能认定事件风险为空。','核对事项适用范围、金额/股比、执行期限与后续进展。'),extra:eventList(c)}
 ];return stock[i]}
function financialHistory(c){const rows=c.r.financial_history||[];return rows.length?`<div class="table-wrap"><table><thead><tr><th>累计报告期</th><th>营收</th><th>归母净利</th><th>经营现金</th><th>披露日期</th></tr></thead><tbody>${rows.slice(0,8).map(r=>`<tr><td>${r.REPORT_DATE?.slice(0,10)}</td><td>${billions(r.TOTALOPERATEREVE)}</td><td>${billions(r.PARENTNETPROFIT)}</td><td>${billions(r.NETCASH_OPERATE_PK)}</td><td>${r.NOTICE_DATE?.slice(0,10)||'—'}</td></tr>`).join('')}</tbody></table></div><div class="panel-note">为各年累计报告期，不能直接把不同季度累计金额当成单季环比。</div>`:''}
function flowTable(c){return c.flows.length?`<div class="table-wrap"><table><thead><tr><th>日期</th><th>超大单+大单净额</th><th>全分类净额</th></tr></thead><tbody>${c.flows.slice(-10).reverse().map(r=>`<tr><td>${r.date}</td><td class="num ${cls(r.netFlow)}">${billions(r.netFlow)}</td><td>${billions(r.totalNetFlow)}</td></tr>`).join('')}</tbody></table></div>`:''}
function coverage(c){return [c.bars.length>=20,c.a.type==='etf'?!!c.etf.holdings?.length:E.valid(c.f.revenue),c.a.type==='etf'?!!c.nav:E.valid(c.f.pe)||E.valid(c.f.ps),c.a.type==='etf'?E.valid(c.m?.vr):c.flows.length>0,c.bars.length>=60,!!c.m&&!!(c.f.period||c.etf.period),c.events.length>0]}
function researchV4(){const c=ctx(),i=state.dimension,d=dimData(c,i),ready=coverage(c);return title('个股七维分析','从数据到解释，再到反证；每项证据保留来源与时间。',selectAsset()+button('信号与回测',"go('backtest')",true,'smile'))+stockHeader()+`<div class="research-layout"><aside class="panel"><div class="panel-head"><h2>七维研究地图</h2>${pill(ready.filter(Boolean).length+' / 7有数据','good')}</div><div class="coverage-summary"><strong>${ready.filter(Boolean).length}<small>/ 7</small></strong><p>可用维度，不代表投资评分</p></div><ul class="dimension-list">${DIMENSIONS.map((dim,j)=>`<li><button class="${i===j?'active':''}" onclick="state.dimension=${j};render()"><span>0${j+1} ${c.a.type==='etf'&&j===1?'成分与盈利':dim.name}</span>${pill(ready[j]?'有数据':'源未返回',ready[j]?'good':'warn')}</button></li>`).join('')}</ul>${provenance(c)}</aside><section class="panel"><div class="dimension-summary"><div class="chip-line">${pill('0'+(i+1)+' / '+DIMENSIONS[i].name,'good')}${pill(c.live?'含盘中数据':'最新收盘','neutral')}</div><h2>${DIMENSIONS[i].title}</h2><p>${c.a.questions[i%3]}</p></div><div class="evidence-metrics">${d.rows.map(([label,value])=>`<div><small>${label}</small><strong>${value}</strong></div>`).join('')}</div><div class="panel-body">${d.read}</div>${d.extra||''}<div class="conclusion"><h3>失效条件</h3><p>${DIMENSIONS[i].invalidate}</p><div class="actions" style="margin-top:15px">${button('深入对应模块',`go('${DIMENSIONS[i].page}')`,true)}${button('记录判断与反证',"noteDialog()")}</div></div><div class="panel-note">${sourceLink(c.f.source_url||c.r.provider_url||'https://gu.qq.com/'+(c.a.code.startsWith('6')?'sh':'sz')+c.a.code,'数据来源')}${c.f.cash_source_url?' · '+sourceLink(c.f.cash_source_url,'现金流原始字段'):''}。结论由页内规则生成；不将最新财务回填到历史回测。</div></section></div>`}
function sentimentV4(){const c=ctx(),s=sentimentRead(c),checks=[['归母与扣非均为正',c.f.profit>0&&c.f.deductProfit>0],['经营现金为正',c.f.operatingCash>0],['收入累计同比为正',c.f.revenueGrowth>0],['负债率已披露',E.valid(c.f.debtRatio)]];return title('市场情绪偏离','用已披露经营事实检验价格压力，识别需要继续核实的分化。',selectAsset())+attribution(0)+`<div class="metrics">${metric('价格压力筛选',s.pressure?'已触发':'未触发','120日≤−20% 或20日落后宽基≥20个百分点')}${metric('近120观察日',change(c.m?.ret120),'不足120条保持空缺')}${metric('相对'+c.benchmark+'（各自20日）',E.valid(c.rel20)?num(c.rel20)+'pp':'—','20日价格表现差')}${metric('现金 / 净利润',num(c.f.cashRatio)+'×',c.f.period||'ETF应穿透成分')}</div><div class="grid-two">${panel(s.label,`<div class="panel-body">${finding(s.label,s.text,'暂时性与结构性问题仍需订单、价格、客户及治理证据；不输出伪造的修复概率。',s.pressure?'warn':'neutral')}${c.a.type==='etf'?etfRead(c):financialRead(c)}</div>`)}${panel('基本面验证清单',`<div class="panel-body">${checks.map(([label,pass])=>`<div class="definition-row"><span>${label}</span><strong>${pill(c.f.period?(pass?'满足':'未满足'):'数据不足',pass?'good':'warn')}</strong></div>`).join('')}${provenance(c)}<div class="actions" style="margin-top:15px">${button('检查估值兑现',"go('valuation')",true)}${button('记录问题性质',"noteDialog('情绪偏离')")}</div></div>`)}</div>${panel('资金与价格的另一份证据',`<div class="panel-body">${flowRead(c)}</div>${flowTable(c)}`)}${panel('近期公司披露：催化剂及反证入口',eventList(c))}`}
const originalValuation=valuation;
function valuationV4(){const c=ctx();return originalValuation()+`<div style="margin-top:18px">${panel('根据已披露数据生成的解读',`<div class="panel-body">${c.a.type==='etf'?etfRead(c):valuationRead(c)}${c.a.type==='etf'?'':financialRead(c)}${provenance(c)}${c.f.source_url?sourceLink(c.f.source_url,'查看原始财务数据'):''}</div>`)}${c.a.type==='etf'?'':panel('财务历史与报告期对照',financialHistory(c))}</div>`}
function etfValuationV4(){const c=ctx();return `<div class="metrics">${metric('最新交易价格',num(c.m?.price,3),c.live?'盘中未确认':'最新收盘')}${metric('最近单位净值',num(c.nav?.value,4),c.nav?.date||'来源未返回')}${metric('前十大占净值',change(c.etf.top10_weight),c.etf.period||'季报持仓未返回')}${metric('已披露持股',(c.etf.holdings||[]).length+'只','存在季报披露滞后')}</div><div class="grid-two">${panel('成分结构与集中度',holdingsTable(c))}${panel('交易价格与净值口径',`<div class="panel-body">${dimData(c,2).read}${etfRead(c)}${c.nav?sourceLink(c.nav.url,'单位净值历史'):''}</div>`)}</div>`}
function marketConclusion(){const rows=BENCH_CODES.map(code=>({a:byCode(code),r:obs(code),m:E.metrics(series(code))})).filter(x=>x.m?.ma10),weak=rows.filter(x=>x.m.price<x.m.ma10).length,strong=rows.filter(x=>x.m.price>x.m.ma60).length,hs=rows.find(x=>x.a.code==='510300')?.m,small=rows.find(x=>x.a.code==='512100')?.m,tech=rows.find(x=>x.a.code==='588080')?.m,spread=E.valid(small?.ret20)&&E.valid(hs?.ret20)?small.ret20-hs.ret20:null,ts=E.valid(tech?.ret20)&&E.valid(hs?.ret20)?tech.ret20-hs.ret20:null;return {rows,weak,strong,spread,ts,label:rows.length<6?'覆盖不足':weak>=4?'ETF趋势代理偏弱':weak<=1?'ETF趋势代理偏强':'宽基趋势分化'}}
function externalV4(){const external=data().external||[],fresh=external.filter(x=>!x.stale),semis=fresh.filter(x=>['usSOXX','usMU','usTSM','usNVDA','usAVGO'].includes(x.symbol)),negative=semis.filter(x=>x.change<0).length;return `<div class="grid-two">${panel('外围科技：价格证据与产业传导',`<div class="panel-body">${finding('半导体及算力代理',semis.length?`${semis.length}个有效样本中有${negative}个最近一日下跌。SOXX用于观察美股半导体交易风险，英伟达/美光/台积电分别对应算力、存储、制造链。`:'没有足够的新鲜跨市场样本，保持判断空缺。','价格同向变化可以提示风险偏好，不能代替订单、资本开支和实际收入证据。',negative>=3?'warn':'neutral')}${finding('传导到你的研究池','光迅科技/长飞光纤关注互联订单和交付；长鑫科技关注存储价格及扩产折旧；中芯国际关注利用率和资本开支。','将海外价格、国内ETF相对表现与各公司现金流合并验证，不能机械映射隔夜涨跌。')}</div>`)}${panel('时间与可用性',`<div class="panel-body"><p class="muted small">A股、港股与美股处于不同时段。以下分别标注供应商时间；过期读数不参与归纳。宏观数据为日频时，不冒充实时行情。</p>${provenance(ctx())}</div>`)}</div><div class="table-wrap panel"><table><thead><tr><th>外围标的</th><th>价格</th><th>最近一日</th><th>供应商时间 / 时区</th><th>状态 / 来源</th></tr></thead><tbody>${external.map(x=>`<tr><td>${esc(x.name)}</td><td class="num">${num(x.price)}</td><td class="num ${cls(x.change)}">${change(x.change)}</td><td>${esc(x.timestamp)}<div class="table-sub">${esc(x.timezone)}</div></td><td>${pill(x.stale?'过期，不参与判断':'有效快照',x.stale?'warn':'good')} ${sourceLink(x.url,'来源')}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">外围接口未返回。</td></tr>'}</tbody></table></div>`}
function marketV4(){const q=marketConclusion(),selected=BENCH_CODES.includes(state.code)?state.code:'588080',a=byCode(selected),b=series(selected),m=E.metrics(b),sectors=data().sectors||[];return '<div class="market-analysis-page">'+title('市场与行业','市场结构 → 行业代理 → 公司经营 → 外围验证。',pill(isDemo()?'合成演示':'可追溯数据','good'))+`<div class="metrics">${metric('市场技术状态',q.label,'六ETF代理，不等同全A市场宽度')}${metric('低于MA10',q.weak+' / '+q.rows.length,'研究过滤阈值4/6')}${metric('小盘相对大盘',E.valid(q.spread)?num(q.spread)+'pp':'—','中证1000−沪深300，20日')}${metric('科创相对大盘',E.valid(q.ts)?num(q.ts)+'pp':'—','科创50−沪深300，20日')}</div>${panel('市场结构解读',`<div class="panel-body analysis-grid">${finding(q.label,q.rows.length===6?`六类ETF中${q.weak}只低于MA10，${q.strong}只高于MA60。${q.weak>=4?'短期弱势覆盖多个宽基/风格代理，不能将单一股票反弹视作全市场拐点。':'需观察均线位置和相对收益是否持续，而非仅观察单日涨跌。'}`:'六类ETF覆盖不完整，不输出完整市场状态。','按历史信号日使用相同过滤口径；盘中状态仍会变化。',q.weak>=4?'warn':'neutral')}${finding('大小盘与科技的差异',`过去20个观察日，小盘相对沪深300${E.valid(q.spread)?num(q.spread)+'个百分点':'样本不足'}，科创50相对沪深300${E.valid(q.ts)?num(q.ts)+'个百分点':'样本不足'}。${q.ts<0?'科技代理跑输宽基，科技个股需要更强的经营与量价证据。':'相对表现并不自动表示估值便宜或行业景气改善。'}`,'继续观察相对收益、年化波动和现金盈利能否同向改善。')}</div>`)}<div class="filter-tabs panel-space">${[['bench','六ETF与行业'],['external','外围与产业传导'],['flow','资金与经营交叉']].map(([id,label])=>`<button class="filter-chip ${state.market===id?'active':''}" onclick="state.market='${id}';render()">${label}</button>`).join('')}</div>${state.market==='external'?externalV4():state.market==='flow'?marketFlowV4():`${benchmarkCards(selected)}${panel(a.name+' · 历史价格与研究入口',b.length?`<div class="chart-wrap">${lineChart(b.slice(-100).map(x=>x.close),{height:230,labels:[b.at(-Math.min(100,b.length)).date,b.at(-1).date]})}</div><div class="panel-note">${sourceLine(selected)} · ${b.at(-1)?.completed===false?'当前末根未收盘':'末根已收盘'}</div>`:'<div class="empty">价格未返回</div>',button('打开交互K线',`setAsset('${selected}','backtest')`,true))}<div style="margin-top:18px">${panel('科技与半导体行业代理',`<div class="panel-body">${sectors.map(s=>{const sm=E.metrics(s.bars);return finding(s.name,`20日涨跌${change(sm?.ret20)}，距60日最高收盘${change(sm?.drawdown)}，最新价${num(sm?.price,3)}${sm?.price<sm?.ma60?'低于':'高于'}MA60。${s.code==='512480'?'与长鑫科技/中芯国际的经营、资本开支和折旧交叉观察。':'与光迅科技/长飞光纤的订单、盈利与现金流交叉观察。'}`,'该ETF为行业交易代理；覆盖与自选公司业务并不完全一致。',sm?.ret20<0?'warn':'neutral')}).join('')||'<p class="muted small">行业代理接口未返回，不以股票涨跌拼造行业指数。</p>'}</div>`)}</div>${panel('研究池：价格、增长与现金的同屏核对',researchPoolTable())}`}`+'</div>'}
function researchPoolTable(){return `<div class="table-wrap"><table><thead><tr><th>标的</th><th>20日价格</th><th>营收同比</th><th>净利同比</th><th>经营现金</th><th>现金 / 净利</th><th>报告期</th></tr></thead><tbody>${WATCH_CODES.map(ctx).map(c=>`<tr><td><button class="stock-link" onclick="setAsset('${c.a.code}','research')">${c.a.name}</button></td><td class="${cls(c.m?.ret20)}">${change(c.m?.ret20)}</td><td>${change(c.f.revenueGrowth)}</td><td>${change(c.f.profitGrowth)}</td><td>${billions(c.f.operatingCash,c.f.currency||c.a.currency||'CNY')}</td><td>${num(c.f.cashRatio)}×</td><td>${c.f.period||c.etf.period||'ETF / 未返回'}</td></tr>`).join('')}</tbody></table></div>`}
function marketFlowV4(){return `<div class="grid-two">${panel('个股资金统计的证据',`<div class="panel-body">${WATCH_CODES.map(ctx).filter(c=>c.a.type==='stock').map(c=>finding(c.a.name,c.flows.length?`截至${c.flows.at(-1).date}近5条分类净额${billions(c.flow5)}；同期价格趋势${trend(c.m).text}。`:'接口未返回有效资金流，保持缺失。',c.f.period?`再核对${c.f.period}经营现金${billions(c.f.operatingCash,c.f.currency||c.a.currency||'CNY')}；公司现金流与二级市场资金流是不同概念。`:'财务披露尚未返回。',c.flow5<0?'warn':'neutral')).join('')}</div>`)}${panel('四种口径不能互相替代',`<div class="panel-body">${[['大单统计','按供应商交易分类汇总，不是机构真实账户。'],['公司经营现金','财报累计经营活动净现金，与股票交易资金不同。'],['ETF份额申赎','需份额与净值数据，不用成交量或股票资金流替代。'],['北向与一致预期','没有获取有效披露时保持缺失，不补造实时净流入。']].map(([t,p])=>finding(t,p,'保留单位、时间及来源后再比较。')).join('')}</div>`)}</div>`}
const originalDataCenter=dataCenter;
function dataCenterV4(){return originalDataCenter()+verificationPanel()}
const originalFactors=factors;
function factorsV4(){return `<div class="actions panel-space">${button('使用已接入的质量 / 低波 / 规模',"state.weights=[0,0,1,1,1,0];render()",true)}${button('恢复完整六因子',"factorPreset('equal')")}</div>`+originalFactors()+panel('实际子指标与缺失原因',`<div class="table-wrap"><table class="wrap-table"><thead><tr><th>股票</th><th>已披露ROE / 现金利润比</th><th>估值口径</th><th>不能补造的指标</th></tr></thead><tbody>${WATCH_CODES.map(ctx).filter(c=>c.a.type==='stock').map(c=>`<tr><td>${c.a.name}</td><td>${change(c.f.roe)} / ${num(c.f.cashRatio)}</td><td>PE ${num(c.f.pe,1)} / PB ${num(c.f.pb,1)}<div class="table-sub">${c.f.period||'财务未返回'}</div></td><td>一致预期修正、前瞻增长、完整EBIT/EBITDA与可验证EV未全部接入；缺失的完整因子不评分。</td></tr>`).join('')}</tbody></table></div>`)}
window.research=researchV4;window.sentiment=sentimentV4;window.valuation=valuationV4;window.etfValuation=etfValuationV4;window.market=marketV4;window.factors=factorsV4;

window.dataCenter=dataCenterV4;
